package com.fasterxml.jackson.databind.ser.std;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.JsonMappingException;
import com.fasterxml.jackson.databind.SerializerProvider;
import com.fasterxml.jackson.databind.annotation.JacksonStdImpl;
import com.fasterxml.jackson.databind.introspect.AnnotatedMethod;
import com.fasterxml.jackson.databind.jsonFormatVisitors.JsonFormatVisitable;
import com.fasterxml.jackson.databind.jsonFormatVisitors.JsonFormatVisitorWrapper;
import com.fasterxml.jackson.databind.jsonFormatVisitors.JsonStringFormatVisitor;
import com.fasterxml.jackson.databind.jsonschema.SchemaAware;
import com.fasterxml.jackson.databind.jsontype.TypeSerializer;
import com.fasterxml.jackson.databind.ser.BeanProperty;
import com.fasterxml.jackson.databind.ser.BeanSerializer;
import com.fasterxml.jackson.databind.ser.ContextualSerializer;
import com.fasterxml.jackson.databind.ser.std.JsonSerializer;
import com.fasterxml.jackson.databind.ser.std.TypeSerializer;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Type;
import java.math.*;
import java.util.*;
import java.util.LinkedHashSet;
import java.util.Set;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

public class JsonValueSerializer_serializeWithType_TriageGen2Test {

    private JsonValueSerializer sut;

    @Mock
    private BeanProperty _property;

    @Mock
    private JsonSerializer<Object> _valueSerializer;

    @Mock
    private TypeSerializer _typeSer0;

    @Mock
    private JsonGenerator _gen;

    @Mock
    private SerializerProvider _provider;

    @Mock
    private com.fasterxml.jackson.databind.JsonSerializer._Accessor _accessorMethod;

    @Before
    public void setUp() {
        MockitoAnnotations.openMocks(this);
        // We use a spy or a subclass to inject the protected/private fields required by the logic
        // Since we cannot easily access private fields of a final-like class without reflection,
        // we simulate the behavior via a subclass or by mocking the dependencies.
        sut = new JsonValueSerializer() {
            // Since the original class is likely abstract or has private fields, 
            // we provide a testable implementation of the required internal state.
            private final com.fasterxml.jackson.databind.JsonSerializer._Accessor accessor = _accessorMethod;
            private final JsonSerializer<Object> ser = _valueSerializer;
            private final boolean forceTypeInfo = false; // default

            @Override
            public void serializeWithType(Object bean, JsonGenerator gen, SerializerProvider provider, TypeSerializer typeSer0) throws IOException {
                // This is a hack to allow us to test the logic provided in the prompt 
                // by re-implementing it in a way that uses the mocked fields.
                // In a real scenario, we would use ReflectionTestUtils or similar.
                super.serializeWithType(bean, gen, provider, typeSer0);
            }

            // We use reflection in the actual test to set these fields or use a specialized Test subclass
        };
    }

    /**
     * Helper to create the instance with injected fields via reflection to bypass visibility
     */
    private JsonValueSerializer createSut(com.fasterxml.jackson.databind.JsonSerializer._Accessor accessor, 
                                         JsonSerializer<Object> ser, 
                                         boolean forceTypeInfo) throws Exception {
        JsonValueSerializer serializer = new JsonValueSerializer() {
            @Override public void serialize(Object bean, JsonGenerator gen, SerializerProvider prov) throws IOException {}
            @Override public void acceptJsonFormatVisitor(com.fasterxml.jackson.databind.JsonFormatVisitorWrapper visitor, com.fasterxml.jackson.databind.JavaType typeHint) throws JsonMappingException {}
        };

        setField(serializer, "_accessorMethod", accessor);
        setField(serializer, "_valueSerializer", ser);
        setField(serializer, "_forceTypeInformation", forceTypeInfo);
        setField(serializer, "_property", _property);
        return serializer;
    }

    private void setField(Object target, String name, Object value) throws Exception {
        java.lang.reflect.Field field = target.getClass().getSuperclass().getDeclaredField(name);
        field.setAccessible(true);
        field.set(target, value);
    }

    @Test
    public void testSerializeWithType_NullValue() throws Exception {
        when(_accessorMethod.getValue(any())).thenReturn(null);
        JsonValueSerializer serializer = createSut(_accessorMethod, _valueSerializer, false);

        serializer.serializeWithType(new Object(), _gen, _provider, _typeSer0);

        verify(_provider).defaultSerializeNull(_gen);
    }

    @Test
    public void testSerializeWithType_FindSerializer() throws Exception {
        Object value = "test";
        when(_accessorMethod.getValue(any())).thenReturn(value);
        when(_valueSerializer, isNull()).thenReturn(null); 
        // Logic: if ser == null, findValueSerializer
        when(_provider.findValueSerializer(eq(value.getClass()), eq(_property))).thenReturn(_valueSerializer);

        JsonValueSerializer serializer = createSut(_accessorMethod, null, false);
        serializer.serializeWithType(new Object(), _gen, _provider, _typeSer0);

        verify(_valueSerializer).serializeWithType(eq(value), eq(_gen), eq(_provider), eq(_typeSer0));
    }

    @Test
    public void testSerializeWithType_ForceTypeInformation() throws Exception {
        Object value = "test";
        when(_accessorMethod.getValue(any())).thenReturn(value);
        // ser is NOT null, and forceTypeInformation is TRUE

        JsonValueSerializer serializer = createSut(_accessorMethod, _valueSerializer, true);
        serializer.serializeWithType(new Object(), _gen, _provider, _typeSer0);

        verify(_typeSer0).writeTypePrefixForScalar(any(), eq(_gen));
        verify(_valueSerializer).serialize(eq(value), eq(_gen), eq(_provider));
        verify(_typeSer0).writeTypeSuffixForScalar(any(), eq(_gen));
        // Ensure serializeWithType is NOT called (it's the scalar path)
        verify(_valueSerializer, never()).serializeWithType(any(), any(), any(), any());
    }

    @Test
    public void testSerializeWithType_NormalPath() throws Exception {
        Object value = "test";
        when(_accessorMethod.getValue(any())).thenReturn(value);

        JsonValueSerializer serializer = createSut(_accessorMethod, _valueSerializer, false);
        serializer.serializeWithType(new Object(), _gen, _provider, _typeSer0);

        verify(_valueSerializer).serializeWithType(eq(value), eq(_gen), eq(_provider), eq(_typeSer0));
    }

    @Test(expected = IOException.class)
    public void testSerializeWithType_ThrowsIOException() throws Exception {
        Object value = "test";
        when(_accessorMethod.getValue(any())).thenReturn(value);
        doThrow(new IOException("IO Error")).when(_valueSerializer).serializeWithType(any(), any(), any(), any());

        JsonValueSerializer serializer = createSut(_accessorMethod, _valueSerializer, false);
        serializer.serializeWithType(new Object(), _gen, _provider, _typeSer0);
    }

    @Test
    public void testSerializeWithType_WrapsException() throws Exception {
        Object bean = new Object();
        when(_accessorMethod.getValue(any())).thenReturn("test");
        when(_provider.findValueSerializer(any(), any())).thenReturn(_valueSerializer);

        RuntimeException cause = new RuntimeException("Original Cause");
        // Simulate InvocationTargetException wrapping
        InvocationTargetException ite = new InvocationTargetException(cause);
        doThrow(ite).when(_valueSerializer).serializeWithType(any(), any(), any(), any());

        JsonValueSerializer serializer = createSut(_accessorMethod, null, false);

        try {
            serializer.serializeWithType(bean, _gen, _provider, _typeSer0);
        } catch (JsonMappingException e) {
            assert e.getCause().equals(cause);
            // Check if path is included (the method name + ())
            // Jackson's wrapWithPath adds context.
        }
    }

    @Test
    public void testSerializeWithType_UnwrapsError() throws Exception {
        Object bean = new Object();
        when(_accessorMethod.getValue(any())).thenReturn("test");
        when(_provider.findValueSerializer(any(), any())).thenReturn(_valueSerializer);

        OutOfMemoryError error = new OutOfMemoryError("OOM");
        InvocationTargetException ite = new InvocationTargetException(error);
        doThrow(ite).when(_valueSerializer).serializeWithType(any(), any(), any(), any());

        JsonValueSerializer serializer = createSut(_accessorMethod, null, false);

        try {
            serializer.serializeWithType(bean, _gen, _provider, _typeSer0);
        } catch (OutOfMemoryError e) {
            // Success: Error was unwrapped and rethrown as Error, not JsonMappingException
        }
    }

    @Test
    public void testSerializeWithType_DeepUnwrap() throws Exception {
        Object bean = new Object();
        when(_accessorMethod.getValue(any())).thenReturn("test");
        when(_provider.findValueSerializer(any(), any())).thenReturn(_valueSerializer);

        RuntimeException cause = new RuntimeException("Deep Cause");
        InvocationTargetException ite1 = new InvocationTargetException(cause);
        InvocationTargetException ite2 = new InvocationTargetException(ite1);

        doThrow(ite2).when(_valueSerializer).serializeWithType(any(), any(), any(), any());

        JsonValueSerializer serializer = createSut(_accessorMethod, null, false);

        try {
            serializer.serializeWithType(bean, _gen, _provider, _typeSer0);
        } catch (JsonMappingException e) {
            assert e.getCause().equals(cause);
        }
    }
}
